window.renderBreadcrumb = function (pageNameOrItems, containerId = 'breadcrumb-container') {
  const container = document.getElementById(containerId);
  if (!container) return;

  if (pageNameOrItems == null) {
    container.innerHTML = '';
    return;
  }

  let items;
  if (Array.isArray(pageNameOrItems)) {
    items = pageNameOrItems;
  } else if (typeof pageNameOrItems === 'string') {
    items = [
      { label: 'Home', link: '/' },
      { label: pageNameOrItems }
    ];
  } else {
    container.innerHTML = '';
    return;
  }

  const chevron = '<svg class="w-3.5 h-3.5 flex-shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M9 18l6-6-6-6"/></svg>';

  const html = items.map(function (item, index) {
    const label = typeof item === 'string' ? item : item.label;
    const isLast = index === items.length - 1;

    let linkHtml;
    if (isLast) {
      linkHtml = '<span class="text-sm text-gray-800 dark:text-white/90 font-medium truncate max-w-[200px]">' + label + '</span>';
    } else {
      var attrs = '';
      var href = item.link || (item.action || item.xOnClick ? 'javascript:void(0)' : '#');
      if (item.xOnClick) {
        attrs += ' href="' + href + '" x-on:click.prevent="' + item.xOnClick + '"';
      } else if (item.action) {
        attrs += ' href="' + href + '" onclick="' + item.action + '"';
      } else {
        attrs += ' href="' + href + '"';
      }
      linkHtml = '<a class="text-sm text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200"' + attrs + '>' + label + '</a>';
    }

    if (index === 0) {
      return '<li>' + linkHtml + '</li>';
    }
    return '<li class="flex items-center gap-1.5">' + chevron + linkHtml + '</li>';
  }).join('');

  container.innerHTML = '<nav aria-label="Breadcrumb"><ol class="flex flex-wrap items-center gap-1.5 text-sm">' + html + '</ol></nav>';
};
